import{_ as t,o as a,c as r,O as n}from"./chunks/framework.4XV3vnnU.js";const p=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/plugins.md","filePath":"documentation/plugins.md","lastUpdated":1793117788000}'),i={name:"documentation/plugins.md"};function d(o,e,s,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p>Plugins connect external systems to the catalog. Each one runs as a sidecar next to the catalog, reads from its system and reports nodes and relations. This page gives an overview of the plugins that ship with Naira. The detailed documentation of each plugin, including every environment variable, is the README in its source directory under <a href="https://github.com/naira-project/naira/tree/main/plugins/cmd" target="_blank" rel="noreferrer"><code>plugins/cmd</code></a>.</p><h2 id="available-plugins" tabindex="-1">Available plugins <a class="header-anchor" href="#available-plugins" aria-label="Permalink to &quot;Available plugins&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plugin</th><th>Reads from</th><th>Emits</th><th>In the Helm chart</th></tr></thead><tbody><tr><td><a href="https://github.com/naira-project/naira/tree/main/plugins/cmd/litellm" target="_blank" rel="noreferrer">litellm</a></td><td>A LiteLLM gateway</td><td>Models, the inference endpoints serving them with usage metrics, MCP servers proxied by LiteLLM</td><td>Enabled by default</td></tr><tr><td><a href="https://github.com/naira-project/naira/tree/main/plugins/cmd/mlflow" target="_blank" rel="noreferrer">mlflow</a></td><td>An MLflow tracking server</td><td>Registered models and datasets</td><td>Enabled by default</td></tr><tr><td><a href="https://github.com/naira-project/naira/tree/main/plugins/cmd/openmetadata" target="_blank" rel="noreferrer">openmetadata</a></td><td>An OpenMetadata instance</td><td>Datasets</td><td>Enabled by default</td></tr><tr><td><a href="https://github.com/naira-project/naira/tree/main/plugins/cmd/mcp_servers" target="_blank" rel="noreferrer">mcp_servers</a></td><td>MCP servers addressed directly</td><td>MCP servers and the tools they expose</td><td>Enabled by default</td></tr><tr><td><a href="https://github.com/naira-project/naira/tree/main/plugins/cmd/depl_calls_svc" target="_blank" rel="noreferrer">depl_calls_svc</a></td><td>The Kubernetes API</td><td>Deployments, Services and which deployment calls which service, found by scanning environment variables for service hostnames</td><td>Enabled by default</td></tr><tr><td><a href="https://github.com/naira-project/naira/tree/main/plugins/cmd/fluxcd" target="_blank" rel="noreferrer">fluxcd</a></td><td>The Kubernetes API</td><td>FluxCD Kustomizations, HelmReleases and GitRepositories, the Deployments they manage and the GitHub repositories they reference</td><td>Enabled by default</td></tr><tr><td><a href="https://github.com/naira-project/naira/tree/main/plugins/cmd/depl_uses_litellm" target="_blank" rel="noreferrer">depl_uses_litellm</a></td><td>The Kubernetes API and LiteLLM</td><td>Which deployments use which LiteLLM models, found by matching API keys in Secrets</td><td>Available, off by default (reads Secrets cluster-wide)</td></tr><tr><td><a href="https://github.com/naira-project/naira/tree/main/plugins/cmd/github" target="_blank" rel="noreferrer">github</a></td><td>GitHub</td><td>Repositories that provably built the images running in the cluster, with CODEOWNERS ownership, linked to their deployments</td><td>Available, off by default (needs a token)</td></tr><tr><td><a href="https://github.com/naira-project/naira/tree/main/plugins/cmd/tech_radar" target="_blank" rel="noreferrer">tech_radar</a></td><td>A mounted YAML file</td><td>The Tech Radar and its entries</td><td>Available, off by default (needs the file)</td></tr><tr><td><a href="https://github.com/naira-project/naira/tree/main/plugins/cmd/bedrock" target="_blank" rel="noreferrer">bedrock</a></td><td>AWS Bedrock and CloudWatch</td><td>Foundation models and, per region with traffic, their inference endpoints with usage and health</td><td>Not yet in the chart</td></tr><tr><td><a href="https://github.com/naira-project/naira/tree/main/plugins/cmd/openai_api_models" target="_blank" rel="noreferrer">openai_api_models</a></td><td>Any OpenAI API compatible <code>/v1/models</code> endpoint</td><td>Models</td><td>Not yet in the chart</td></tr><tr><td><a href="https://github.com/naira-project/naira/tree/main/plugins/cmd/thalamus" target="_blank" rel="noreferrer">thalamus</a>, <a href="https://github.com/naira-project/naira/tree/main/plugins/cmd/depl_uses_thalamus" target="_blank" rel="noreferrer">depl_uses_thalamus</a></td><td>The Thalamus serving operator</td><td>Models served by Thalamus and the deployments using them</td><td>Not yet in the chart, experimental third-party contribution</td></tr></tbody></table><p>Plugin names in the chart use hyphens (<code>depl-calls-svc</code>), source directories use underscores (<code>depl_calls_svc</code>).</p><h2 id="how-plugins-are-configured" tabindex="-1">How plugins are configured <a class="header-anchor" href="#how-plugins-are-configured" aria-label="Permalink to &quot;How plugins are configured&quot;">​</a></h2><p>In the Helm chart, one entry under <code>catalog.plugins.&lt;name&gt;</code> drives everything about a plugin: whether it is enabled, its image, its port inside the pod, its cron schedule, its environment variables, Secret references, RBAC rules and mounted config files. See <a href="/pr-preview/pr-12/documentation/deployment">Deployment</a> and the <a href="https://github.com/naira-project/naira/tree/main/deploy/charts/naira#plugins" target="_blank" rel="noreferrer">chart README</a>.</p><p>A few conventions hold across plugins:</p><ul><li><strong><code>PATH_PREFIX</code></strong> sets the prefix of the node paths a plugin emits, for example <code>litellm</code> produces <code>litellm/gpt-4o</code>. Run the same plugin twice with different prefixes to catalog two instances of a system.</li><li><strong>Credentials</strong> are read from environment variables that the chart fills from a Secret. A plugin never stores credentials.</li><li><strong>Schedules</strong> are cron expressions. A plugin without a schedule only runs when triggered from the Plugins page or the API.</li><li><strong>Kubernetes access</strong> uses the in-cluster service account by default. A <code>KUBECONFIG</code> style variable points to a kubeconfig file for local runs.</li></ul><h2 id="running-a-plugin-on-its-own" tabindex="-1">Running a plugin on its own <a class="header-anchor" href="#running-a-plugin-on-its-own" aria-label="Permalink to &quot;Running a plugin on its own&quot;">​</a></h2><p>Every plugin binary can run outside the catalog, which helps when developing or when checking what a plugin would report against a real system. Started with the <code>-mermaid</code> flag, it performs one collect, prints the result as a Mermaid graph and exits. With <code>-neo4j &lt;prefix&gt;</code> it prints Cypher statements instead, and with <code>-neo4j-url</code> it pushes the result into a Neo4j database for exploration.</p><h2 id="contributing-a-plugin" tabindex="-1">Contributing a plugin <a class="header-anchor" href="#contributing-a-plugin" aria-label="Permalink to &quot;Contributing a plugin&quot;">​</a></h2><p>Plugins are the main extension point of Naira, and new ones are welcome. <a href="/pr-preview/pr-12/documentation/plugin-authoring">Writing a Plugin</a> walks through the contract and the project conventions. The longer-term model for distributing plugins maintained outside the core team is discussed in <a href="https://github.com/naira-project/architecture/blob/main/rfc/rfc-010-plugin-ecosystem.md" target="_blank" rel="noreferrer">RFC-010</a>.</p>',13)])])}const g=t(i,[["render",d]]);export{p as __pageData,g as default};
